function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 3 || n > 100000) return 'n is an integer from 3 to 10^5.';
  if (!Array.isArray(edges) || edges.length < 2 || edges.length > 100000) return 'edges needs 2 to 10^5 edges.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || b < 1 || a > n || b > n) return 'Edge endpoints are nodes from 1 to n.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const key = Math.min(a, b) * 200000 + Math.max(a, b);
    if (seen.has(key)) return 'Each edge may appear only once.';
    seen.add(key);
  }
  return null;
}

