function isPossible(n, edges) {
  const degree = new Array(n + 1).fill(0);
  const linked = new Set();
  for (const [a, b] of edges) {
    degree[a]++;
    degree[b]++;
    linked.add(a * (n + 1) + b);
    linked.add(b * (n + 1) + a);
  }
  const free = (a, b) => !linked.has(a * (n + 1) + b);

  const odd = [];
  for (let node = 1; node <= n; node++) {
    if (degree[node] % 2 === 1) odd.push(node);
  }

  if (odd.length === 0) return true;
  if (odd.length === 2) {
    const [a, b] = odd;
    if (free(a, b)) return true;
    for (let node = 1; node <= n; node++) {
      if (node !== a && node !== b && free(a, node) && free(b, node)) return true;
    }
    return false;
  }
  if (odd.length === 4) {
    const [a, b, c, d] = odd;
    if (free(a, b) && free(c, d)) return true;
    if (free(a, c) && free(b, d)) return true;
    return free(a, d) && free(b, c);
  }
  return false;
}

