function isPossible(n, edges) {
  const present = new Set(edges.map(([a, b]) => `${Math.min(a, b)},${Math.max(a, b)}`));
  const missing = [];
  for (let a = 1; a <= n; a++)
    for (let b = a + 1; b <= n; b++)
      if (!present.has(`${a},${b}`)) missing.push([a, b]);
  const allEven = (extra) => {
    const count = new Array(n + 1).fill(0);
    for (const [a, b] of [...edges, ...extra]) { count[a]++; count[b]++; }
    return count.every(d => d % 2 === 0);
  };
  if (allEven([])) return true;
  for (let i = 0; i < missing.length; i++) {
    if (allEven([missing[i]])) return true;
    for (let j = i + 1; j < missing.length; j++) if (allEven([missing[i], missing[j]])) return true;
  }
  return false;
}

