function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  for (;;) {
    const mode = pick(4);
    const n = large ? (mode === 2 ? 600 + pick(401) : 50 + pick(99951)) : 3 + pick(6);
    const keys = new Set();
    const edges = [];
    const add = (a, b) => {
      const key = Math.min(a, b) * 200000 + Math.max(a, b);
      if (a === b || keys.has(key)) return false;
      keys.add(key);
      edges.push(rand() < 0.5 ? [a, b] : [b, a]);
      return true;
    };
    const isNew = (a, b) => a !== b && !keys.has(Math.min(a, b) * 200000 + Math.max(a, b));
    const distinct = (k) => {
      const chosen = new Set();
      while (chosen.size < k) chosen.add(1 + pick(n));
      return [...chosen];
    };
    if (mode === 0) {
      // Arbitrary edges: usually many odd nodes on large inputs, anything on small ones.
      const m = large ? 1000 + pick(1000) : 2 + pick(10);
      for (let t = 0; t < 3 * m && edges.length < m; t++) add(1 + pick(n), 1 + pick(n));
    } else if (mode === 2) {
      // Two hubs joined to each other and to (almost) every other node: the hard case for two odd nodes.
      const [a, b] = distinct(2);
      add(a, b);
      const skip = rand() < 0.5 ? 1 + pick(n) : 0;
      for (let node = 1; node <= n; node++) {
        if (node !== a && node !== b && node !== skip) { add(a, node); add(b, node); }
      }
    } else {
      // Edge-disjoint cycles keep every degree even; then a few edges create odd nodes.
      const target = large ? 1500 + pick(400) : pick(8);
      for (let t = 0; t < (large ? 3000 : 20) && edges.length < target; t++) {
        const cycle = distinct(3 + pick(Math.min(n, large ? 12 : n) - 2));
        if (cycle.every((v, i) => isNew(v, cycle[(i + 1) % cycle.length]))) cycle.forEach((v, i) => add(v, cycle[(i + 1) % cycle.length]));
      }
      if (mode === 1) {
        const extra = pick(3);
        for (let t = 0; t < extra; t++) add(1 + pick(n), 1 + pick(n));
      } else if (n >= 4) {
        // Make four chosen nodes odd with a matching, a star or all six edges among them.
        const [a, b, c, d] = distinct(4);
        const patterns = [[[a, b], [c, d]], [[a, c], [b, d]], [[a, d], [b, c]], [[a, b], [a, c], [a, d]], [[b, a], [b, c], [b, d]], [[a, b], [a, c], [a, d], [b, c], [b, d], [c, d]]];
        const pattern = patterns[pick(patterns.length)];
        if (pattern.every(([u, v]) => isNew(u, v))) pattern.forEach(([u, v]) => add(u, v));
      }
    }
    if (edges.length < 2 || edges.length > (large ? 2000 : 28)) continue;
    for (let i = edges.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [edges[i], edges[j]] = [edges[j], edges[i]];
    }
    return [n, edges];
  }
}
